import CryptoKit
import Foundation
@testable import SnippetsCore

// With `--linux-fixtures <dir>`, `emit` also runs the current Swift code over the
// independent fixtures in snippets-linux/tests/fixtures and prints one `drift-check`
// line per file. Nothing here changes a vector file: these fixtures were generated by
// other implementations (Python + OpenSSL, the Swift 6.2 runtime), so agreement is
// evidence in both directions and a mismatch is news.

enum FixtureAudit {
    static func run(directory: String) -> [String] {
        let root = URL(fileURLWithPath: directory, isDirectory: true)
        func json(_ name: String) -> [String: Any]? {
            guard let data = try? Data(contentsOf: root.appendingPathComponent(name)) else { return nil }
            return (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
        }
        var lines: [String] = []

        // swift-double-v1.tsv: bit pattern, tab, Double.description.
        if let text = try? String(contentsOf: root.appendingPathComponent("swift-double-v1.tsv"), encoding: .utf8) {
            var total = 0, mismatches = 0
            var first: String?
            for line in text.split(separator: "\n") {
                let parts = line.split(separator: "\t", omittingEmptySubsequences: false)
                guard parts.count == 2, let bits = UInt64(parts[0], radix: 16) else { continue }
                total += 1
                let printed = Double(bitPattern: bits).description
                if printed != parts[1] {
                    mismatches += 1
                    if first == nil { first = "\(parts[0]): fixture \(parts[1]), this toolchain \(printed)" }
                }
            }
            lines.append(mismatches == 0
                ? "swift-double-v1.tsv: Double.description of this toolchain matches all \(total) lines"
                : "swift-double-v1.tsv: DRIFT, \(mismatches) of \(total) lines differ (first: \(first ?? "?"))")
        }

        // sync-wire-v1.json: wire records sealed by an independent implementation.
        if let fixture = json("sync-wire-v1.json"),
           let key = (fixture["rootKeyHex"] as? String).flatMap({ Data(hex: $0) }),
           let salt = (fixture["saltHex"] as? String).flatMap({ Data(hex: $0) }),
           let records = fixture["records"] as? [[String: Any]] {
            let sealer = SnippetCryptoSealer(
                keyring: SnippetCrypto.Keyring(libraryKey: SymmetricKey(data: key), salt: salt), scopeID: "sync-v1")
            var opened = 0
            for record in records {
                guard let wire = record["wire"] as? [String: Any],
                      let id = (wire["id"] as? String).flatMap(UUID.init(uuidString:)),
                      let rev = wire["rev"] as? String, let deleted = wire["deleted"] as? Bool,
                      let blob = (wire["blob"] as? String).flatMap({ Data(base64Encoded: $0) }),
                      let envelope = try? WireCodec.open(
                        WireRecord(id: id, rev: rev, deleted: deleted, blob: blob), using: sealer),
                      (try? envelope.envelopeHash()) == record["hash"] as? String,
                      (try? String(decoding: envelope.canonicalData(), as: UTF8.self)) == record["canonical"] as? String
                else { continue }
                opened += 1
            }
            lines.append(opened == records.count
                ? "sync-wire-v1.json: WireCodec opens all \(records.count) records; canonical bytes and hashes agree"
                : "sync-wire-v1.json: DRIFT, only \(opened) of \(records.count) records open and agree")
        }

        // crypto-v1.json: a whole vault document.
        if let fixture = json("crypto-v1.json"), let documentObject = fixture["document"],
           let documentData = try? JSONSerialization.data(withJSONObject: documentObject),
           let document = try? VaultFile.decode(documentData),
           let root = (fixture["rootKeyHex"] as? String).flatMap({ Data(hex: $0) }),
           let salt = document.vaultSaltBytes {
            let keyring = SnippetCrypto.Keyring(libraryKey: SymmetricKey(data: root), salt: salt)
            var problems: [String] = []
            for record in document.records {
                guard let plaintext = try? SnippetCrypto.open(
                    record.sealed, for: SnippetCrypto.RecordContext(scopeID: document.kid, recordID: record.id),
                    keyring: keyring) else { problems.append("record does not open"); continue }
                if String(decoding: plaintext, as: UTF8.self) != fixture["plaintext"] as? String { problems.append("plaintext differs") }
                if SnippetCrypto.contentHash(of: plaintext, keyring: keyring) != record.contentHash { problems.append("contentHash differs") }
            }
            if let wrap = document.wrapRecovery,
               let material = (fixture["recoveryMaterialHex"] as? String).flatMap({ Data(hex: $0) }) {
                let key = try? KeyWrap.unwrap(wrap, under: material, purpose: .recovery, kid: document.kid, salt: salt)
                if key?.raw != root { problems.append("recovery wrap does not yield the root key") }
            }
            if let wrapped = document.passphraseWrap, let passphrase = fixture["passphrase"] as? String {
                let key = try? PassphraseKDF.unwrap(wrapped, passphrase: passphrase, kid: document.kid)
                if key?.raw != root { problems.append("passphrase wrap does not yield the root key") }
            }
            lines.append(problems.isEmpty
                ? "crypto-v1.json: VaultFile decodes it; \(document.records.count) record(s), the recovery wrap and the passphrase wrap open to the fixture's key and plaintext"
                : "crypto-v1.json: DRIFT, \(problems.joined(separator: "; "))")
        }

        // backup-v1.json: hazard H2 as Swift actually behaves.
        if let fixture = json("backup-v1.json"), let containerObject = fixture["container"],
           let container = try? JSONSerialization.data(withJSONObject: containerObject),
           let password = fixture["password"] as? String {
            do {
                let opened = try EncryptedSnippetBackup.open(container, passphrase: password)
                let records = opened.vault?.records ?? []
                let lost = records.filter { $0.createdAt == .distantPast || $0.updatedAt == .distantPast }.count
                lines.append("backup-v1.json: EncryptedSnippetBackup.open accepts it (\(opened.ordinaryCount) ordinary, \(records.count) secure); "
                    + (lost == 0
                        ? "vault record dates survive"
                        : "H2 CONFIRMED, \(lost) of \(records.count) secure record(s) come back with Date.distantPast because the fixture writes their dates as ISO-8601 strings"))
            } catch {
                lines.append("backup-v1.json: EncryptedSnippetBackup.open refuses it with \(errorName(error))")
            }
        }

        // bootstrap-v1.json: the portable key bundle.
        if let fixture = json("bootstrap-v1.json"),
           let material = (fixture["material"] as? String).flatMap({ Data(base64Encoded: $0) }),
           let expected = fixture["bundleJSON"] as? String {
            let produced = (try? LibraryKeyBootstrap.PortableKeyBundle(material: material).jsonData)
                .map { String(decoding: $0, as: UTF8.self) }
            lines.append(produced == expected
                ? "bootstrap-v1.json: PortableKeyBundle.jsonData equals the fixture's bundleJSON"
                : "bootstrap-v1.json: DRIFT in bundleJSON")
        }
        return lines
    }
}
